-- Повторные одинаковые доставки допустимы; конфликт JSON на позиции или event_id, а также конфликт версии запрещены.
SELECT count(*) AS n FROM (SELECT min(event_id) AS k FROM {{target:oil_stg__v_event_parsed}} GROUP BY topic,kafka_partition,kafka_offset HAVING topic IS NULL OR kafka_partition IS NULL OR kafka_partition<0 OR kafka_offset IS NULL OR kafka_offset<0 OR count(DISTINCT event_json)>1 OR count_if(event_json IS NULL)>0 UNION ALL SELECT event_id AS k FROM {{target:oil_stg__v_event_parsed}} GROUP BY event_id HAVING event_id IS NULL OR count(DISTINCT event_json)>1 UNION ALL SELECT min(event_id) AS k FROM {{target:oil_stg__v_event_parsed}} GROUP BY event_type,entity_id,entity_version HAVING count(DISTINCT event_id)>1) q;
